def solve(n, k, a):
    prefix_xor = [0] * (n + 1)
    xor_count = {0: 1}
    max_segments = 0
    current_xor = 0

    for i in range(n):
        current_xor ^= a[i]
        prefix_xor[i + 1] = current_xor

        for j in range(k):
            flipped_xor = current_xor ^ (1 << j)
            if flipped_xor in xor_count:
                max_segments = max(max_segments, i + 1 - xor_count[flipped_xor])

        if current_xor in xor_count:
            max_segments = max(max_segments, i + 1 - xor_count[current_xor])
        else:
            xor_count[current_xor] = i + 1

    return max_segments

# Read input
n, k = map(int, input().split())
a = list(map(int, input().split()))

# Solve and print result
result = solve(n, k, a)
print(result)
